CREATE TABLE IF NOT EXISTS crm_leads (id UUID PRIMARY KEY, data JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS crm_deals (id UUID PRIMARY KEY, lead_id UUID NOT NULL REFERENCES crm_leads(id) ON DELETE RESTRICT, data JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS crm_deals_lead_idx ON crm_deals(lead_id);
CREATE TABLE IF NOT EXISTS crm_settings (id INTEGER PRIMARY KEY CHECK(id=1), data JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS crm_administrator (id INTEGER PRIMARY KEY CHECK(id=1), user_id TEXT NOT NULL UNIQUE REFERENCES "user"(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS crm_events (id UUID PRIMARY KEY, action TEXT NOT NULL, timestamp TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS crm_events_timestamp_idx ON crm_events(timestamp DESC);
CREATE TABLE IF NOT EXISTS crm_imports (id TEXT PRIMARY KEY, imported_at TIMESTAMPTZ NOT NULL DEFAULT now());
